/** Live issues currently assigned to one user. Archived rows are left out. */
export async function listLiveIssuesByAssignee(
  orgId: OrgId,
  assigneeId: UserId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.assigneeId, assigneeId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .all();

  return rows.map((row) => toIssue(row));
}

