 * Drops the assignee from every live issue held by a member who is leaving
 * the organization. One `issue.unassigned` is published per issue; archived
 * issues keep their assignee.
 */
export async function unassignIssuesForRemovedMember(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const assigned = await issueRepo.listLiveIssuesByAssignee(orgId, userId);

  for (const issue of assigned) {
    await issueRepo.setIssueAssignee(orgId, issue.id, null);
